{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.DASH_PROD_SUMMARY COPY GRANTS AS WITH as_of AS ( SELECT LEAST( MAX(date), DATEADD(day, -1, CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())::DATE) ) AS d FROM snitch_db.maplemonk.horizontal_sales_categories ), sales AS ( SELECT s.SKU_GROUP, SUM(IFF(s.date = a.d, s.gross_quantity, 0)) AS gq_1d, SUM(IFF(s.date > DATEADD(day, -7, a.d), s.gross_quantity, 0)) AS gq_7d, SUM(s.gross_quantity) AS gq_30d FROM snitch_db.maplemonk.horizontal_sales_categories s CROSS JOIN as_of a WHERE s.date > DATEADD(day, -30, a.d) AND s.date <= a.d AND s.type = \'Shopify\' GROUP BY s.SKU_GROUP ), returns_data AS ( SELECT SKU_GROUP, DIV0NULL(SUM(return_qty), SUM(sales_qty)) AS return_pct FROM snitch_db.maplemonk.return_fact_items GROUP BY 1 ), base AS ( SELECT sku_group, category, original_price, cost_price, current_slashed_price, final_live_date AS live_date, image_url, online_inventory, CASE WHEN category IN (\'Sunglasses\',\'Perfumes\',\'Bags\',\'Luggage\',\'Belts\') THEN 1.18 WHEN category IN (\'Shoes\',\'Shirts\',\'T-Shirts\',\'Trousers\',\'Jeans\',\'Chinos\',\'Cargo Pants\', \'Jackets\',\'Overshirt\',\'Blazers\',\'Co-ords\',\'Shorts\',\'Sweaters\',\'Hoodies\', \'Sweatshirts\',\'Joggers & Trackpants\',\'Pyjamas\',\'Boxers\',\'Inner Wear\') AND current_slashed_price > 2500 THEN 1.18 ELSE 1.05 END AS gst_factor, title, case when current_slashed_price<>original_price then \'discount\' else \'non-discount\' end as discount_filter, ONLINE_SKU_CLASS, COLOR, FIT, STYLE, COLLAR_MAPPED as collar, SLEEVES_TYPE, occassion, MATERIAL_MAPPED as material, print_design_mapped as print, case when category in (\'Sunglasses\',\'Perfumes\',\'Bags\',\'Luggage\',\'Belts\',\'Shoes\') then \'no\' when (left(sku_group,4) = \'4MBG\' or left(sku_group,2) = \'4B\') and online_xl3_units >5 and online_xl4_units >5 and online_xl5_units >5 then \'no\' when online_s_units > 5 and online_m_units >5 and online_l_units >5 then \'no\' else \'yes\' end as cut_filter from snitch_db.maplemonk.base_product qualify row_number() over (partition by sku_group order by online_inventory desc) = 1 ), prod_details AS ( SELECT *, case when left(sku_group,4) = \'4MBG\' or left(sku_group,2) = \'4B\' then \'plus\' else \'snitch\' end as plus_filter, case when category in (\'Sunglasses\',\'Perfumes\',\'Bags\',\'Luggage\',\'Belts\',\'Shoes\') then \'longtail\' when category in (\'Jackets\',\'Overshirt\',\'Sweaters\',\'Hoodies\',\'Sweatshirts\') then \'winter\' when category in (\'Shirts\',\'T-Shirts\',\'Trousers\',\'Jeans\') then \'core\' else \'non-core\' end as category_groups, DIV0NULL(original_price / gst_factor - cost_price, original_price / gst_factor) AS gm_pct FROM base ) SELECT p.*, ret.RETURN_PCT, a.d AS AS_OF_DATE, DATEDIFF(day, p.LIVE_DATE, a.d) + 1 AS DAYS_LIVE, COALESCE(s.gq_1d, 0) AS ROS_1D, COALESCE(s.gq_7d, 0) / LEAST(7, GREATEST(COALESCE(DAYS_LIVE, 7), 1)) AS ROS_7D, COALESCE(s.gq_30d, 0) / LEAST(30, GREATEST(COALESCE(DAYS_LIVE, 30), 1)) AS ROS_30D, case when p.sku_group in (\'4MSS2998-02\', \'4JE082-01\', \'4MCR1001-04\', \'4MCR1002-04\', \'4MCR1002-05\', \'4MCR1002-06\', \'4MCR1004-06\', \'4MCR1004-08\', \'4MCR1007-01\', \'4MCR1007-02\', \'4MCR1007-04\', \'4MCR1007-05\', \'4MCR1008-01\', \'4MCR1008-03\', \'4MCR1010-01\', \'4MCR1010-02\', \'4MCR1016-01\', \'4MCRT0002-02\', \'4MSC4015-03\', \'4MSD4208-04\', \'4MSK8624-01\', \'4MSK8624-02\', \'4MSK8629-01\', \'4MSK8683-01\', \'4MSK8683-02\', \'4MSK8699-01\', \'4MSK8732-02\', \'4MSK8742-01\', \'4MSK8742-02\', \'4MSK8743-01\', \'4MSK8743-02\', \'4MSK8748-01\', \'4MSK8748-02\', \'4MSK8770-01\', \'4MSK8770-02\', \'4MSK8770-03\', \'4MSK8770-04\', \'4MSNJ0054-01\', \'4MSR5081-01\', \'4MSR5116-01\', \'4MSR5173-06\', \'4MSR5194-03\', \'4MSR5195-04\', \'4MSR5375-01\', \'4MSR5515-05\', \'4MSR5534-01\', \'4MSS1216-07\', \'4MSS1244-03\', \'4MSS1490-01\', \'4MSS1490-02\', \'4MSS1490-03\', \'4MSS1538-01\', \'4MSS1813-01\', \'4MSS1813-02\', \'4MSS1813-04\', \'4MSS1813-05\'