 when p.sku_group in (\'4MSS3012-02\', \'4MSS3976-01\', \'4MSS1108-01\', \'4MSS1813-03\', \'4MSS1813-06\', \'4MSS1813-08\', \'4MSS1813-10\', \'4MSS3208-01\', \'4MSS3468-01\', \'4MSS3976-08\', \'4JE039-01\', \'4MCR1007-03\', \'4MSD3514-01\', \'4MSD3518-01\', \'4MSD3529-03\', \'4MSD3653-02\', \'4MSD3667-05\', \'4MSD3719-01\', \'4MSD3774-02\', \'4MSD3864-01\', \'4MSD4041-03\', \'4MSD4094-01\', \'4MSD4116-01\', \'4MSD4116-02\', \'4MSD4116-05\', \'4MSD4207-01\', \'4MSD4211-01\', \'4MSR5163-01\', \'4MSR5163-05\', \'4MSR5194-01\', \'4MSS1052-01\', \'4MSS1052-03\', \'4MSS1052-04\', \'4MSS1389-04\', \'4MSS1535-01\', \'4MSS1593-01\', \'4MSS2355-05\', \'4MSS3012-01\', \'4MSS3012-03\', \'4MSS3036-05\', \'4MSS3208-02\', \'4MSS3208-08\', \'4MSS3218-07\', \'4MSS3288-08\', \'4MSS3307-05\', \'4MSS3361-01\', \'4MSS3387-01\', \'4MSS3446-02\', \'4MSS3457-05\', \'4MSS3457-06\', \'4MSS3489-02\', \'4MSS3490-01\', \'4MSS3563-05\', \'4MSS3563-07\', \'4MSS3967-05\', \'4MSS3976-04\', \'4MSS3976-14\', \'4MSS4021-01\', \'4MSS4021-03\', \'4MSS4181-03\', \'4MSS4217-01\', \'4MSS4225-01\', \'4MSS4276-01\', \'4MSS4431-08\', \'4MSS4597-01\', \'4MSS4681-01\', \'4MSS4681-03\', \'4MSS4708-02\', \'4MSS4753-01\', \'4MSS4753-02\', \'4MSS4758-06\', \'4MST040-01\', \'4MST2378-01\', \'4MST2388-01\', \'4MST2418-02\', \'4MST2418-03\', \'4MST2440-02\', \'4MST2440-03\', \'4MST2567-01\', \'4MST2661-01\', \'4MST2663-01\', \'4MST2672-03\', \'4MST2728-02\', \'4MST2729-02\', \'4MST2737-02\', \'4MST2763-01\', \'4MST2764-02\', \'4MST2771-02\', \'4MST2801-03\', \'4MST2827-01\', \'4MST3127-01\', \'4MSS4717-03\', \'4MSS4717-06\', \'4MSS4717-08\', \'4MSS4717-10\', \'4MSS4718-01\', \'4MSS4718-03\', \'4MSS4718-04\') then \'noos\' else \'no\' end as repeat_filter FROM prod_details p CROSS JOIN as_of a LEFT JOIN sales s ON s.SKU_GROUP = p.SKU_GROUP LEFT JOIN returns_data ret ON ret.SKU_GROUP = p.SKU_GROUP ; CREATE OR REPLACE TABLE snitch_db.maplemonk.DASH_PROD_SALES_600D COPY GRANTS AS WITH as_of AS ( SELECT LEAST( MAX(date), DATEADD(day, -1, CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())::DATE) ) AS d FROM snitch_db.maplemonk.horizontal_sales_categories ), spine AS ( SELECT DATEADD(day, -(ROW_NUMBER() OVER (ORDER BY SEQ4()) - 1), a.d) AS SALES_DATE FROM TABLE(GENERATOR(ROWCOUNT => 600)) CROSS JOIN as_of a ), daily AS ( SELECT s.SKU_GROUP, s.date AS sales_date, SUM(s.gross_quantity) AS gross_quantity FROM snitch_db.maplemonk.horizontal_sales_categories s CROSS JOIN as_of a WHERE s.date > DATEADD(day, -600, a.d) AND s.date <= a.d AND s.type = \'Shopify\' GROUP BY s.SKU_GROUP, s.date ), base_product_pre as ( select SKU_GROUP, final_live_date from snitch_db.maplemonk.base_product qualify row_number() over (partition by SKU_GROUP order by online_inventory desc) = 1 ) SELECT p.SKU_GROUP, sp.SALES_DATE, COALESCE(d.gross_quantity, 0) AS GROSS_QUANTITY FROM base_product_pre p JOIN spine sp ON sp.SALES_DATE >= COALESCE(p.final_live_date, \'1900-01-01\'::DATE) LEFT JOIN daily d ON d.SKU_GROUP = p.SKU_GROUP AND d.SALES_DATE = sp.SALES_DATE ; CREATE TABLE IF NOT EXISTS snitch_db.maplemonk.DASH_META ( REFRESHED_AT TIMESTAMP_NTZ, AS_OF_DATE DATE, SKU_COUNT NUMBER ); INSERT INTO snitch_db.maplemonk.DASH_META (REFRESHED_AT, AS_OF_DATE, SKU_COUNT) SELECT CURRENT_TIMESTAMP()::TIMESTAMP_NTZ, MAX(AS_OF_DATE), COUNT(*) FROM snitch_db.maplemonk.DASH_PROD_SUMMARY;",
